package com.autoops.workflow.controller;import com.autoops.workflow.entity.Workflow;import com.autoops.workflow.repository.WorkflowRepository;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/workflows")public class WorkflowController{private final WorkflowRepository repo;public WorkflowController(WorkflowRepository r){repo=r;}@GetMapping public List<Workflow> list(){return repo.findByCreatedByAndDeletedAtIsNull(1L);}@PostMapping public Workflow create(@RequestBody Workflow w){w.setCreatedBy(1L);return repo.save(w);}}
